// Natura PvP: an automated PvP map with three modes (Emparejamiento, Caza, Campal),
// a lobby and an admin panel. Generated by tools/natura_pvp.py.
import * as mc from "@minecraft/server";
import * as ui from "@minecraft/server-ui";
import { AREA, CAMPAL, campalSpawns, DUEL, duelSpawns, HUNT, huntSurface, inHunt, insideArea, LOBBY } from "./gen.js";
import { buildArea, progress, rebuildColumns } from "./builder.js";
import { clearPlayer, DEFAULT_KITS, describeKit, getKit, giveKit, KIT_IDS, MENU_LORE, resetKit, saveKitFrom, scaledHuntedKit } from "./kits.js";

const { system, world, ItemStack } = mc;
const CFG = __CONFIG__;
const SEC = 20;
const ADMIN_TAG = "admin";
const MUSIC = "natura.epic";

// ------------------------------------------------------------ helpers
const enumv = (E, name) => E?.[name] ?? E?.[name.toLowerCase()];
const GM = {
  adventure: enumv(mc.GameMode, "Adventure"),
  survival: enumv(mc.GameMode, "Survival"),
  spectator: enumv(mc.GameMode, "Spectator"),
  creative: enumv(mc.GameMode, "Creative"),
};
const overworld = () => world.getDimension("minecraft:overworld");
const sleep = (ticks) => new Promise((r) => system.runTimeout(r, ticks));
const valid = (e) => {
  try {
    return !!e && e.isValid !== false && (typeof e.isValid !== "function" || e.isValid());
  } catch {
    return false;
  }
};
const byId = (id) => {
  try {
    const e = world.getEntity(id);
    return valid(e) ? e : undefined;
  } catch {
    return undefined;
  }
};
const isAdmin = (p) => p.hasTag(ADMIN_TAG);
const fmtTime = (s) => `${Math.floor(s / 60)}:${String(Math.max(0, s) % 60).padStart(2, "0")}`;
const shuffle = (a) => {
  for (let i = a.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [a[i], a[j]] = [a[j], a[i]];
  }
  return a;
};

function cmd(text) {
  try {
    return overworld().runCommand(text);
  } catch {
    return undefined;
  }
}

function pcmd(player, text) {
  try {
    return player.runCommand(text);
  } catch {
    return undefined;
  }
}

function title(player, main, sub = "", stay = 30) {
  try {
    player.onScreenDisplay.setTitle(main, { subtitle: sub, fadeInDuration: 2, stayDuration: stay, fadeOutDuration: 8 });
  } catch {}
}

function bar(player, text) {
  try {
    player.onScreenDisplay.setActionBar(text);
  } catch {}
}

function sound(player, id, volume = 1, pitch = 1) {
  try {
    player.playSound(id, { volume, pitch });
  } catch {}
}

function effect(player, id, seconds, amp = 0) {
  try {
    player.addEffect(id, Math.max(1, Math.round(seconds * SEC)), { amplifier: amp, showParticles: false });
  } catch {}
}

function clearEffects(player) {
  try {
    for (const e of player.getEffects()) player.removeEffect(e.typeId);
  } catch {}
}

function heal(player) {
  clearEffects(player);
  try {
    player.getComponent("minecraft:health")?.resetToMaxValue();
  } catch {}
  try {
    player.extinguishFire(false);
  } catch {}
  effect(player, "saturation", 1, 20);
}

function setMode(player, gm) {
  try {
    if (player.getGameMode() !== gm) player.setGameMode(gm);
  } catch {}
}

function tp(player, loc, facing) {
  try {
    player.teleport({ x: loc.x, y: loc.y, z: loc.z }, { dimension: overworld(), facingLocation: facing ?? loc.facing, keepVelocity: false });
  } catch {}
}

const dist2 = (a, b) => (a.x - b.x) ** 2 + (a.z - b.z) ** 2;

async function showForm(player, form) {
  for (let i = 0; i < 40; i++) {
    let r;
    try {
      r = await form.show(player);
    } catch {
      return undefined;
    }
    if (r.canceled && String(r.cancelationReason) === "UserBusy") {
      await sleep(5);
      continue;
    }
    return r;
  }
  return undefined;
}

// ------------------------------------------------------------ settings
const DEFAULTS = {
  duel: { enabled: true, countdown: 9, maxTime: 300, arenas: 2 },
  hunt: {
    enabled: true, maxPlayers: 5, minPlayers: 2, lobbyCountdown: 30, headStart: 20, timeLimit: 600,
    reveal: 60, music: true, friendlyFire: false, fullRegenEvery: 5,
  },
  campal: { enabled: true, reward: true, spawnProtection: 3, combatTag: 8, sidebar: true },
  world: { time: 2, lockTime: true, weather: 0, lockWeather: true, naturalRegen: true },
};
let S = structuredCloneSafe(DEFAULTS);

function structuredCloneSafe(o) {
  return JSON.parse(JSON.stringify(o));
}

function loadSettings() {
  S = structuredCloneSafe(DEFAULTS);
  try {
    const saved = JSON.parse(world.getDynamicProperty("natura:settings") ?? "{}");
    for (const k of Object.keys(S)) Object.assign(S[k], saved[k] ?? {});
  } catch {}
}

function saveSettings() {
  world.setDynamicProperty("natura:settings", JSON.stringify(S));
}

const TIMES = [["Amanecer", 23000], ["Mañana", 1000], ["Mediodía", 6000], ["Atardecer", 12000], ["Noche", 14000], ["Medianoche", 18000]];
const WEATHERS = [["Despejado", "clear"], ["Lluvia", "rain"], ["Tormenta", "thunder"]];

function applyWorld() {
  const w = S.world;
  cmd(`gamerule dodaylightcycle ${!w.lockTime}`);
  cmd(`time set ${TIMES[w.time]?.[1] ?? 6000}`);
  cmd(`gamerule doweathercycle ${!w.lockWeather}`);
  cmd(`weather ${WEATHERS[w.weather]?.[1] ?? "clear"}`);
  cmd(`gamerule naturalregeneration ${w.naturalRegen}`);
}

function applyGamerules() {
  for (const rule of [
    "keepinventory true", "doimmediaterespawn true", "domobspawning false", "dofiretick false", "mobgriefing false",
    "tntexplodes false", "doinsomnia false", "commandblockoutput false", "showcoordinates false", "spawnradius 0",
    "pvp true", "falldamage true", "showdeathmessages true", "doentitydrops true", "dotiledrops true",
    "projectilescanbreakblocks false", "dopatrolspawning false", "dotraderspawning false",
  ]) cmd(`gamerule ${rule}`);
  cmd("difficulty normal");
  try {
    world.setDefaultSpawnLocation({ x: Math.floor(LOBBY.spawn.x), y: LOBBY.spawn.y, z: Math.floor(LOBBY.spawn.z) });
  } catch {}
  applyWorld();
}

// ------------------------------------------------------------ stats
let STATS = {};
let statsDirty = false;
const STAT_NAMES = { k: "Bajas", d: "Muertes", dw: "Duelos ganados", dl: "Duelos perdidos", hw: "Cazas ganadas", hl: "Cazas perdidas", ck: "Bajas en campal" };

function loadStats() {
  try {
    STATS = JSON.parse(world.getDynamicProperty("natura:stats") ?? "{}");
  } catch {
    STATS = {};
  }
}

function addStat(player, key, n = 1) {
  const name = typeof player === "string" ? player : player.name;
  const s = (STATS[name] ??= {});
  s[key] = (s[key] ?? 0) + n;
  statsDirty = true;
}

function top(key, n = 3) {
  return Object.entries(STATS).filter(([, s]) => s[key] > 0).sort((a, b) => b[1][key] - a[1][key]).slice(0, n);
}

system.runInterval(() => {
  if (!statsDirty) return;
  statsDirty = false;
  let json = JSON.stringify(STATS);
  // keep the property small: forget the players with fewer games
  while (json.length > 30000) {
    const names = Object.keys(STATS).sort((a, b) => sum(STATS[a]) - sum(STATS[b]));
    for (const n of names.slice(0, Math.ceil(names.length / 10))) delete STATS[n];
    json = JSON.stringify(STATS);
  }
  world.setDynamicProperty("natura:stats", json);
}, 100);

function sum(s) {
  return Object.values(s).reduce((a, b) => a + b, 0);
}

// ------------------------------------------------------------ player state
// mode: lobby | duel | hunt | hunt_spec | campal | free
const P = new Map();

function st(player) {
  let s = P.get(player.id);
  if (!s) {
    s = { mode: "lobby", hurtTick: -9999, attacker: undefined, attackerTick: -9999, pad: null, protectUntil: 0 };
    P.set(player.id, s);
  }
  return s;
}

const built = (id) => world.getDynamicProperty(`natura:built:${id}`) === CFG.buildVersion;

function menuItem(id, name, lore) {
  const item = new ItemStack(id, 1);
  item.nameTag = name;
  try {
    item.setLore([...lore, MENU_LORE]);
  } catch {}
  try {
    item.lockMode = enumv(mc.ItemLockMode, "slot");
  } catch {}
  try {
    item.keepOnDeath = true;
  } catch {}
  return item;
}

const ITEMS = {
  selector: () => menuItem("minecraft:compass", "§a§lSelector de modos", ["§7Úsalo para elegir modo"]),
  admin: () => menuItem("minecraft:clock", "§c§lPanel de administración", ["§7Solo para administradores"]),
  leave: () => menuItem("minecraft:recovery_compass", "§c§lVolver al lobby", ["§7Sal del campal"]),
};

function itemKind(item) {
  if (!item) return undefined;
  let lore = [];
  try {
    lore = item.getLore();
  } catch {}
  if (!lore.includes(MENU_LORE)) return undefined;
  if (item.typeId === "minecraft:compass") return "selector";
  if (item.typeId === "minecraft:clock") return "admin";
  if (item.typeId === "minecraft:recovery_compass") return "leave";
  return undefined;
}

function lobbyItems(player) {
  const inv = player.getComponent("minecraft:inventory")?.container;
  if (!inv) return;
  inv.setItem(0, ITEMS.selector());
  inv.setItem(8, isAdmin(player) ? ITEMS.admin() : undefined);
}

function stopMusic(player) {
  pcmd(player, `stopsound @s ${MUSIC}`);
}

function sendToLobby(player, message) {
  const s = st(player);
  s.mode = "lobby";
  s.role = undefined;
  s.pad = "spawn";
  stopMusic(player);
  setMode(player, GM.adventure);
  clearPlayer(player);
  heal(player);
  effect(player, "resistance", 10, 255);
  tp(player, LOBBY.spawn, { x: 0.5, y: 101, z: -12 });
  try {
    player.setSpawnPoint({ dimension: overworld(), x: Math.floor(LOBBY.spawn.x), y: LOBBY.spawn.y, z: Math.floor(LOBBY.spawn.z) });
  } catch {}
  lobbyItems(player);
  if (message) player.sendMessage(message);
}

function leaveQueues(player) {
  const a = duel.queue.indexOf(player.id);
  if (a >= 0) duel.queue.splice(a, 1);
  const b = hunt.queue.indexOf(player.id);
  if (b >= 0) hunt.queue.splice(b, 1);
}

function inCombat(player) {
  const s = st(player);
  return system.currentTick - s.hurtTick < S.campal.combatTag * SEC;
}

// ------------------------------------------------------------ Emparejamiento (1v1)
const duel = { queue: [], matches: [] };

function freeArena() {
  const n = Math.max(1, Math.min(DUEL.centers.length, S.duel.arenas));
  for (let i = 0; i < n; i++) if (!duel.matches[i] && built(`duel${i}`)) return i;
  return -1;
}

function duelJoin(player) {
  if (!S.duel.enabled) return player.sendMessage("§c[Emparejamiento] El modo está desactivado por un administrador.");
  if (!built("duel0")) return player.sendMessage("§e[Emparejamiento] La arena se está construyendo, espera un momento.");
  if (st(player).mode !== "lobby") return;
  if (duel.queue.includes(player.id)) return player.sendMessage("§e[Emparejamiento] Ya estás en la cola.");
  leaveQueues(player);
  duel.queue.push(player.id);
  sound(player, "random.orb", 0.7, 1.2);
  player.sendMessage(`§b[Emparejamiento]§r Entraste a la cola §7(${duel.queue.length} en cola)§r. Buscando rival...`);
}

function duelLeave(player) {
  const i = duel.queue.indexOf(player.id);
  if (i < 0) return;
  duel.queue.splice(i, 1);
  player.sendMessage("§b[Emparejamiento]§r Saliste de la cola.");
}

function startDuel(i, a, b) {
  const spawns = duelSpawns(i);
  const m = { i, ids: [a.id, b.id], names: [a.name, b.name], spawns, phase: "countdown", t: S.duel.countdown, time: 0 };
  duel.matches[i] = m;
  [a, b].forEach((p, k) => {
    const s = st(p);
    s.mode = "duel";
    s.match = m;
    s.pad = null;
    setMode(p, GM.adventure);
    heal(p);
    tp(p, spawns[k]);
    giveKit(p, getKit("duel"));
    lockEffects(p, S.duel.countdown + 1);
    title(p, "§b§lEMPAREJAMIENTO", `§fcontra §e${k ? a.name : b.name}`, 40);
    p.sendMessage(`§b[Emparejamiento]§r Rival encontrado: §e${k ? a.name : b.name}§r. La pelea empieza en §e${S.duel.countdown}§r segundos.`);
  });
}

function lockEffects(p, seconds) {
  effect(p, "slowness", seconds, 255);
  effect(p, "weakness", seconds, 255);
  effect(p, "resistance", seconds, 255);
}

function unlock(p) {
  for (const e of ["slowness", "weakness", "resistance", "blindness"]) {
    try {
      p.removeEffect(e);
    } catch {}
  }
}

function duelPlayers(m) {
  return m.ids.map(byId);
}

function endDuel(m, winnerIdx, reason) {
  if (m.phase === "end") return;
  m.phase = "end";
  const players = duelPlayers(m);
  if (winnerIdx === undefined) {
    for (const p of players) if (p) title(p, "§e§lEMPATE", reason ?? "");
    world.sendMessage(`§b[Emparejamiento]§r §e${m.names[0]}§r y §e${m.names[1]}§r empataron.`);
  } else {
    const w = players[winnerIdx], l = players[1 - winnerIdx];
    addStat(m.names[winnerIdx], "dw");
    addStat(m.names[1 - winnerIdx], "dl");
    if (w) {
      title(w, "§a§l¡VICTORIA!", `§fderrotaste a §e${m.names[1 - winnerIdx]}`);
      sound(w, "random.levelup");
      unlock(w);
      effect(w, "resistance", 5, 255);
    }
    if (l) title(l, "§c§lDERROTA", `§fte ganó §e${m.names[winnerIdx]}`);
    world.sendMessage(`§b[Emparejamiento]§r §a${m.names[winnerIdx]}§r ganó a §c${m.names[1 - winnerIdx]}§r${reason ? ` §7(${reason})` : ""}.`);
  }
  for (const id of m.ids) {
    const s = P.get(id);
    if (s?.match === m) s.match = undefined;
  }
  system.runTimeout(() => {
    for (const p of duelPlayers(m)) if (p && st(p).mode === "duel") sendToLobby(p);
    if (duel.matches[m.i] === m) duel.matches[m.i] = undefined;
  }, 3 * SEC);
}

function duelTick() {
  // matchmaking
  duel.queue = duel.queue.filter((id) => byId(id) && st(byId(id)).mode === "lobby");
  if (S.duel.enabled) {
    while (duel.queue.length >= 2) {
      const i = freeArena();
      if (i < 0) {
        for (const id of duel.queue) bar(byId(id), "§bEmparejamiento: §fesperando a que se libere una arena...");
        break;
      }
      const a = byId(duel.queue.shift()), b = byId(duel.queue.shift());
      startDuel(i, a, b);
    }
    if (duel.queue.length === 1) bar(byId(duel.queue[0]), "§bEmparejamiento: §fbuscando rival...");
  }
  for (const m of duel.matches) {
    if (!m || m.phase === "end") continue;
    const players = duelPlayers(m);
    if (m.phase === "countdown") {
      if (m.t > 0) {
        for (const p of players) {
          if (!p) continue;
          const c = m.t <= 3 ? "§c" : m.t <= 5 ? "§6" : "§e";
          title(p, `${c}§l${m.t}`, "§7prepárate", 16);
          sound(p, "note.pling", 0.8, m.t <= 3 ? 1.5 : 1);
        }
        m.t--;
      } else {
        m.phase = "fight";
        for (const p of players) {
          if (!p) continue;
          unlock(p);
          title(p, "§a§l¡A PELEAR!", "", 20);
          sound(p, "mob.enderdragon.growl", 0.4, 1.3);
        }
      }
    } else if (m.phase === "fight") {
      m.time++;
      const left = S.duel.maxTime > 0 ? S.duel.maxTime - m.time : undefined;
      for (const p of players) if (p) bar(p, `§b⚔ §f${m.names[0]} §7vs §f${m.names[1]}${left !== undefined ? `  §7| §e${fmtTime(left)}` : ""}`);
      if (left !== undefined && left <= 0) endDuel(m, undefined, "se acabó el tiempo");
    }
  }
}

// ------------------------------------------------------------ Caza (hunt)
const hunt = {
  phase: "idle", queue: [], countdown: 0, hunted: undefined, hunters: [], alive: new Set(), spectators: new Set(),
  names: {}, timeLeft: 0, headLeft: 0, released: 0, music: false, musicNext: 0, dirty: new Set(), matches: 0,
  regen: false, nextHunted: undefined, startCount: 0,
};

function huntJoin(player) {
  if (!S.hunt.enabled) return player.sendMessage("§c[Caza] El modo está desactivado por un administrador.");
  if (!built("hunt")) return player.sendMessage(`§e[Caza] El mapa de caza se está construyendo${progress.busy && progress.label === AREA.hunt.name ? ` (${pct()}%)` : ""}, espera un momento.`);
  if (st(player).mode !== "lobby") return;
  if (hunt.queue.includes(player.id)) return player.sendMessage("§e[Caza] Ya estás en la cola.");
  if (hunt.phase === "running" || hunt.phase === "ending") return player.sendMessage("§e[Caza] Hay una caza en curso. Entra a la cola cuando acabe, o mírala como espectador desde el selector.");
  if (hunt.queue.length >= S.hunt.maxPlayers) return player.sendMessage(`§c[Caza] La caza está llena (${S.hunt.maxPlayers}/${S.hunt.maxPlayers}).`);
  leaveQueues(player);
  hunt.queue.push(player.id);
  sound(player, "random.orb", 0.7, 0.9);
  for (const id of hunt.queue) byId(id)?.sendMessage(`§c[Caza]§r §e${player.name}§r entró a la caza §7(${hunt.queue.length}/${S.hunt.maxPlayers})`);
}

function huntLeave(player) {
  const i = hunt.queue.indexOf(player.id);
  if (i < 0) return;
  hunt.queue.splice(i, 1);
  player.sendMessage("§c[Caza]§r Saliste de la cola.");
}

function huntSpectate(player) {
  if (hunt.phase !== "running") return player.sendMessage("§e[Caza] No hay ninguna caza en curso.");
  leaveQueues(player);
  const s = st(player);
  s.mode = "hunt_spec";
  hunt.spectators.add(player.id);
  clearPlayer(player);
  setMode(player, GM.spectator);
  const target = byId(hunt.hunted);
  tp(player, target ? { x: target.location.x, y: target.location.y + 12, z: target.location.z } : huntCenter());
  player.sendMessage("§c[Caza]§r Estás mirando la caza. Usa §e/natura:lobby§r para volver.");
  if (hunt.music) playMusic(player);
}

function huntCenter() {
  const s = huntSurface(HUNT.cx, HUNT.cz);
  return { x: HUNT.cx + 0.5, y: s.y + 25, z: HUNT.cz + 0.5 };
}

function randomSpot(awayFrom, minDist) {
  let best, bestD = -1;
  for (let i = 0; i < 80; i++) {
    const x = HUNT.x0 + 12 + Math.floor(Math.random() * (HUNT.size - 24));
    const z = HUNT.z0 + 12 + Math.floor(Math.random() * (HUNT.size - 24));
    const s = huntSurface(x, z);
    if (!s.safe) continue;
    const loc = { x: x + 0.5, y: s.y, z: z + 0.5 };
    const d = awayFrom ? Math.sqrt(dist2(loc, awayFrom)) : 1e9;
    if (d >= minDist) return loc;
    if (d > bestD) {
      best = loc;
      bestD = d;
    }
  }
  return best ?? huntCenter();
}

function huntParticipants() {
  return [hunt.hunted, ...hunt.hunters, ...hunt.spectators].map(byId).filter(Boolean);
}

function aliveHunters() {
  return hunt.hunters.filter((id) => hunt.alive.has(id));
}

function startHunt() {
  const ids = hunt.queue.filter((id) => byId(id) && st(byId(id)).mode === "lobby").slice(0, S.hunt.maxPlayers);
  hunt.queue = [];
  if (ids.length < 2) return;
  const huntedId = ids.includes(hunt.nextHunted) ? hunt.nextHunted : ids[Math.floor(Math.random() * ids.length)];
  hunt.nextHunted = undefined;
  hunt.hunted = huntedId;
  hunt.hunters = shuffle(ids.filter((id) => id !== huntedId));
  hunt.alive = new Set(ids);
  hunt.spectators = new Set();
  hunt.names = Object.fromEntries(ids.map((id) => [id, byId(id).name]));
  hunt.startCount = ids.length;
  hunt.timeLeft = S.hunt.timeLimit;
  hunt.headLeft = S.hunt.headStart;
  hunt.released = 0;
  hunt.music = false;
  hunt.phase = "running";
  hunt.dirty.clear();
  world.setDynamicProperty("natura:huntDirty", true);

  const preyLoc = randomSpot(undefined, 0);
  const packLoc = randomSpot(preyLoc, 170);
  const kit = scaledHuntedKit(hunt.hunters.length);
  const prey = byId(huntedId);
  const s = st(prey);
  s.mode = "hunt";
  s.role = "hunted";
  s.pad = null;
  setMode(prey, GM.survival);
  heal(prey);
  tp(prey, preyLoc);
  giveKit(prey, kit);
  system.runTimeout(() => {
    try {
      if (valid(prey)) prey.getComponent("minecraft:health")?.resetToMaxValue();
    } catch {}
  }, 2);
  title(prey, "§c§lERES EL CAZADO", `§f${hunt.hunters.length} cazador(es) te buscan. ¡Corre!`, 60);
  prey.sendMessage(`§c[Caza]§r Eres el §ccazado§r. Tu kit de hierro tiene §e+${kit.bonus}§r de mejora por los ${hunt.hunters.length} cazadores. Ventaja: §e${S.hunt.headStart} s§r.`);
  sound(prey, "mob.wither.spawn", 0.5, 1.2);
  hunt.hunters.forEach((id, k) => {
    const p = byId(id);
    const hs = st(p);
    hs.mode = "hunt";
    hs.role = "hunter";
    hs.pad = null;
    setMode(p, GM.survival);
    heal(p);
    const a = (k / hunt.hunters.length) * Math.PI * 2;
    hs.lockAt = { x: packLoc.x + Math.cos(a) * 2, y: packLoc.y, z: packLoc.z + Math.sin(a) * 2 };
    tp(p, hs.lockAt, preyLoc);
    giveKit(p, getKit("hunter"));
    if (hunt.headLeft > 0) {
      lockEffects(p, hunt.headLeft + 1);
      effect(p, "blindness", hunt.headLeft + 1, 0);
    }
    title(p, "§a§lERES CAZADOR", `§fatrapa a §c${hunt.names[huntedId]}`, 60);
    p.sendMessage(`§c[Caza]§r Eres §acazador§r. Atrapa a §c${hunt.names[huntedId]}§r antes de §e${fmtTime(S.hunt.timeLimit)}§r.`);
  });
  world.sendMessage(`§c[Caza]§r ¡Empieza la caza! §c${hunt.names[huntedId]}§r contra ${hunt.hunters.map((id) => `§a${hunt.names[id]}`).join("§r, ")}§r.`);
  checkMusic();
}

function playMusic(player) {
  stopMusic(player);
  sound(player, MUSIC, 1, 1);
}

function checkMusic() {
  if (hunt.phase !== "running" || !S.hunt.music) return;
  const one = hunt.alive.has(hunt.hunted) && aliveHunters().length === 1;
  if (one && !hunt.music) {
    hunt.music = true;
    hunt.musicNext = system.currentTick + CFG.trackSeconds * SEC;
    for (const p of huntParticipants()) {
      playMusic(p);
      title(p, "§4§l¡DUELO FINAL!", `§c${hunt.names[hunt.hunted]} §7contra §a${hunt.names[aliveHunters()[0]]}`, 50);
    }
  }
}

function huntEliminate(id, killerName, reason) {
  if (hunt.phase !== "running" || !hunt.alive.has(id)) return;
  hunt.alive.delete(id);
  const name = hunt.names[id];
  for (const p of huntParticipants()) {
    p.sendMessage(`§c[Caza]§r ${id === hunt.hunted ? "§c" : "§a"}${name}§r ${reason ?? (killerName ? `fue eliminado por §e${killerName}` : "fue eliminado")}§r.`);
  }
  if (id === hunt.hunted) return endHunt("hunters", killerName ? `${killerName} atrapó a ${name}` : `${name} cayó`);
  addStat(name, "hl");
  const s = P.get(id);
  if (s) {
    s.mode = "hunt_spec";
    hunt.spectators.add(id);
  }
  if (aliveHunters().length === 0) return endHunt("hunted", "todos los cazadores cayeron");
  checkMusic();
}

function endHunt(winner, reason) {
  if (hunt.phase !== "running") return;
  hunt.phase = "ending";
  const preyName = hunt.names[hunt.hunted];
  const winners = winner === "hunted" ? [hunt.hunted] : hunt.hunters;
  for (const id of winners) addStat(hunt.names[id], "hw");
  if (winner === "hunters") addStat(preyName, "hl");
  for (const p of huntParticipants()) {
    const won = winners.includes(p.id);
    title(p, winner === "hunted" ? "§c§lGANA EL CAZADO" : "§a§lGANAN LOS CAZADORES", `§f${reason}`, 70);
    if (won) sound(p, "random.levelup");
    unlock(p);
    effect(p, "resistance", 8, 255);
  }
  world.sendMessage(`§c[Caza]§r ${winner === "hunted" ? `§c${preyName}§r sobrevivió a la caza` : `Los cazadores atraparon a §c${preyName}§r`} §7(${reason})§r.`);
  system.runTimeout(() => {
    cmd(`kill @e[type=item,x=${HUNT.x0},y=${HUNT.floor},z=${HUNT.z0},dx=${HUNT.size},dy=${HUNT.clearTop - HUNT.floor},dz=${HUNT.size}]`);
    cmd(`kill @e[type=arrow,x=${HUNT.x0},y=${HUNT.floor},z=${HUNT.z0},dx=${HUNT.size},dy=${HUNT.clearTop - HUNT.floor},dz=${HUNT.size}]`);
    for (const p of huntParticipants()) {
      const m = st(p).mode;
      if (m === "hunt" || m === "hunt_spec") sendToLobby(p);
    }
    hunt.phase = "idle";
    hunt.hunted = undefined;
    hunt.hunters = [];
    hunt.alive.clear();
    hunt.spectators.clear();
    hunt.music = false;
    hunt.matches++;
    regenHunt(false);
  }, 6 * SEC);
}

function regenHunt(forceFull) {
  if (hunt.regen) return;
  const every = S.hunt.fullRegenEvery;
  const full = forceFull || hunt.dirty.size > 30000 || (every > 0 && hunt.matches % every === 0);
  let keys = null;
  if (!full) {
    keys = new Set();
    for (const key of hunt.dirty) {
      const [x, z] = key.split(",").map(Number);
      for (let dx = -2; dx <= 2; dx++) for (let dz = -2; dz <= 2; dz++) if (inHunt(x + dx, z + dz)) keys.add(`${x + dx},${z + dz}`);
    }
    if (!keys.size) {
      hunt.dirty.clear();
      world.setDynamicProperty("natura:huntDirty", false);
      return;
    }
  }
  hunt.regen = true;
  hunt.dirty.clear();
  const job = full ? buildArea("hunt", true) : rebuildColumns("hunt", keys, "Regenerando la caza");
  for (const p of world.getPlayers()) if (isAdmin(p)) p.sendMessage(`§7[Caza] Regenerando el mapa (${full ? "completo" : `${keys.size} columnas`})...`);
  job.then((ok) => {
    hunt.regen = false;
    if (ok) world.setDynamicProperty("natura:huntDirty", false);
    for (const p of world.getPlayers()) if (isAdmin(p)) p.sendMessage(`§7[Caza] Mapa regenerado${ok ? "" : " con errores"}.`);
  });
}

function huntTick() {
  if (hunt.phase === "idle" || hunt.phase === "countdown") {
    hunt.queue = hunt.queue.filter((id) => byId(id) && st(byId(id)).mode === "lobby");
    const n = hunt.queue.length;
    if (!S.hunt.enabled || n < Math.max(2, S.hunt.minPlayers)) {
      hunt.phase = "idle";
      for (const id of hunt.queue) bar(byId(id), `§cCaza: §fesperando jugadores §7(${n}/${S.hunt.maxPlayers}, mínimo ${Math.max(2, S.hunt.minPlayers)})`);
      return;
    }
    if (hunt.phase === "idle") {
      hunt.phase = "countdown";
      hunt.countdown = S.hunt.lobbyCountdown;
    }
    if (n >= S.hunt.maxPlayers) hunt.countdown = Math.min(hunt.countdown, 5);
    if (hunt.regen) {
      for (const id of hunt.queue) bar(byId(id), `§cCaza: §fregenerando el mapa... §7${pct()}%`);
      return;
    }
    for (const id of hunt.queue) {
      const p = byId(id);
      bar(p, `§cCaza: §fempieza en §e${hunt.countdown}s §7(${n}/${S.hunt.maxPlayers})`);
      if (hunt.countdown <= 5) sound(p, "note.hat", 0.7, 1.4);
    }
    if (hunt.countdown-- <= 0) startHunt();
    return;
  }
  if (hunt.phase !== "running") return;
  // players that left
  for (const id of [...hunt.alive]) if (!byId(id)) huntEliminate(id, undefined, "abandonó la partida");
  if (hunt.phase !== "running") return;
  const prey = byId(hunt.hunted);
  if (hunt.headLeft > 0) {
    hunt.headLeft--;
    if (hunt.headLeft === 0) {
      for (const id of aliveHunters()) {
        const p = byId(id);
        unlock(p);
        title(p, "§a§l¡A CAZAR!", `§fencuentra a §c${hunt.names[hunt.hunted]}`, 30);
        sound(p, "mob.wolf.howl", 1, 0.9);
        st(p).lockAt = undefined;
      }
      if (prey) {
        title(prey, "§c§l¡YA VIENEN!", "", 30);
        sound(prey, "mob.wolf.howl", 1, 0.9);
      }
    }
  } else hunt.released++;
  hunt.timeLeft--;
  if (S.hunt.reveal > 0 && hunt.released > 0 && hunt.released % S.hunt.reveal === 0 && prey) {
    const l = prey.location;
    for (const id of aliveHunters()) {
      const p = byId(id);
      p.sendMessage(`§c[Caza]§r §c${prey.name}§r fue visto en §eX ${Math.round(l.x)}  Y ${Math.round(l.y)}  Z ${Math.round(l.z)}`);
      sound(p, "note.bell", 1, 1.2);
    }
    prey.sendMessage("§c[Caza]§r ¡Los cazadores han visto tu posición!");
    sound(prey, "note.bass", 1, 0.6);
  }
  // HUD
  const hn = aliveHunters().length;
  for (const p of huntParticipants()) {
    const s = st(p);
    let text;
    if (p.id === hunt.hunted) text = `§cCAZADO §7| §fcazadores: §a${hn} §7| §e${fmtTime(hunt.timeLeft)}`;
    else if (s.mode === "hunt" && prey) {
      const d = Math.round(Math.sqrt(dist2(p.location, prey.location)));
      text = hunt.headLeft > 0 ? `§aCAZADOR §7| §fsales en §e${hunt.headLeft}s` : `§aCAZADOR §7| §fpresa: §c${hunt.names[hunt.hunted]} §7~${d > 100 ? "+100" : Math.ceil(d / 10) * 10} bloques §7| §e${fmtTime(hunt.timeLeft)}`;
    } else text = `§7ESPECTADOR §7| §fcazadores: §a${hn} §7| §e${fmtTime(hunt.timeLeft)}`;
    bar(p, text);
  }
  if (hunt.music && system.currentTick >= hunt.musicNext) {
    hunt.musicNext = system.currentTick + CFG.trackSeconds * SEC;
    for (const p of huntParticipants()) playMusic(p);
  }
  if (hunt.timeLeft <= 0) endHunt("hunted", "sobrevivió hasta el final del tiempo");
}

// ------------------------------------------------------------ Campal
const OBJ = "natura_campal";

function campalObjective() {
  return world.scoreboard.getObjective(OBJ) ?? world.scoreboard.addObjective(OBJ, "§a§lCampal §r§7· bajas");
}

function campalSidebar() {
  try {
    const slot = enumv(mc.DisplaySlotId, "Sidebar");
    if (S.campal.sidebar) world.scoreboard.setObjectiveAtDisplaySlot(slot, { objective: campalObjective(), sortOrder: enumv(mc.ObjectiveSortOrder, "Descending") });
    else world.scoreboard.clearObjectiveAtDisplaySlot(slot);
  } catch {}
}

function campalPlayers() {
  return world.getPlayers().filter((p) => st(p).mode === "campal");
}

function campalEnter(player) {
  if (!S.campal.enabled) return player.sendMessage("§c[Campal] La arena está cerrada por un administrador.");
  if (!built("campal")) return player.sendMessage("§e[Campal] La arena se está construyendo, espera un momento.");
  if (st(player).mode !== "lobby") return;
  leaveQueues(player);
  st(player).mode = "campal";
  spawnInCampal(player, true);
  world.sendMessage(`§a[Campal]§r §e${player.name}§r entró a la arena §7(${campalPlayers().length} dentro)`);
}

function spawnInCampal(player, first) {
  const others = campalPlayers().filter((p) => p.id !== player.id).map((p) => p.location);
  let best, bestD = -1;
  for (const sp of campalSpawns()) {
    const d = others.length ? Math.min(...others.map((o) => dist2(o, sp))) : Math.random();
    if (d > bestD) {
      best = sp;
      bestD = d;
    }
  }
  const s = st(player);
  s.pad = null;
  setMode(player, GM.adventure);
  heal(player);
  tp(player, best);
  giveKit(player, getKit("campal"));
  player.getComponent("minecraft:inventory")?.container?.setItem(8, ITEMS.leave());
  if (S.campal.spawnProtection > 0) {
    effect(player, "resistance", S.campal.spawnProtection, 255);
    s.protectUntil = system.currentTick + S.campal.spawnProtection * SEC;
  }
  title(player, "§a§lCAMPAL", first ? "§fla arena siempre está activa" : "§f¡de vuelta a la pelea!", 30);
  try {
    const obj = campalObjective();
    if (!obj.hasParticipant(player)) obj.setScore(player, 0);
  } catch {}
}

function campalLeave(player) {
  if (inCombat(player)) {
    const left = Math.ceil((S.campal.combatTag * SEC - (system.currentTick - st(player).hurtTick)) / SEC);
    return player.sendMessage(`§c[Campal] Estás en combate. Espera ${left} s sin recibir daño para salir.`);
  }
  sendToLobby(player, "§a[Campal]§r Volviste al lobby.");
}

// ------------------------------------------------------------ deaths, damage, leaving
function killerOf(player, source) {
  let k = source?.damagingEntity;
  if (k?.typeId !== "minecraft:player") k = undefined;
  const s = st(player);
  if (!k && s.attacker && system.currentTick - s.attackerTick < 15 * SEC) k = byId(s.attacker);
  return k?.id !== player.id ? k : undefined;
}

world.afterEvents.entityDie.subscribe(({ deadEntity: player, damageSource }) => {
  if (player.typeId !== "minecraft:player") return;
  const s = st(player);
  const killer = killerOf(player, damageSource);
  addStat(player, "d");
  if (killer) addStat(killer, "k");
  s.attacker = undefined;
  if (s.mode === "duel" && s.match) {
    const m = s.match;
    const idx = m.ids.indexOf(player.id);
    s.mode = "lobby";
    endDuel(m, 1 - idx, m.phase === "countdown" ? "murió antes de empezar" : undefined);
  } else if (s.mode === "hunt") {
    huntEliminate(player.id, killer?.name);
  } else if (s.mode === "campal") {
    if (killer && st(killer).mode === "campal") {
      addStat(killer, "ck");
      try {
        campalObjective().addScore(killer, 1);
      } catch {}
      if (S.campal.reward) {
        effect(killer, "regeneration", 4, 2);
        killer.getComponent("minecraft:inventory")?.container?.addItem(new ItemStack("minecraft:golden_apple", 1));
      }
      bar(killer, `§a+1 baja §7(eliminaste a §f${player.name}§7)`);
      sound(killer, "random.orb", 1, 1.6);
    }
    for (const p of campalPlayers()) if (p.id !== player.id) p.sendMessage(`§a[Campal]§r §c${player.name}§r ${killer ? `fue eliminado por §a${killer.name}` : "murió"}§r.`);
  }
}, { entityTypes: ["minecraft:player"] });

world.afterEvents.playerSpawn.subscribe(({ player, initialSpawn }) => {
  const s = st(player);
  if (initialSpawn) {
    P.delete(player.id);
    system.runTimeout(() => {
      if (!valid(player)) return;
      if (!built("lobby")) {
        tp(player, { x: 0.5, y: 106, z: 0.5 });
        effect(player, "slow_falling", 30, 0);
        return;
      }
      sendToLobby(player);
      title(player, "§2§lNATURA PvP", "§fbienvenido", 60);
      player.sendMessage("§2[Natura PvP]§r Pisa una plataforma de colores o usa la §abrújula§r para elegir modo: §bEmparejamiento§r, §cCaza§r o §aCampal§r.");
      if (isAdmin(player)) player.sendMessage("§7Eres administrador: usa el §creloj§7 o §f/natura:admin§7 para abrir el panel.");
    }, 10);
    return;
  }
  // respawn after dying
  system.runTimeout(() => {
    if (!valid(player)) return;
    if (s.mode === "campal" && S.campal.enabled) spawnInCampal(player, false);
    else if (s.mode === "hunt_spec" && hunt.phase === "running") {
      clearPlayer(player);
      setMode(player, GM.spectator);
      tp(player, huntCenter());
      player.sendMessage("§c[Caza]§r Ahora eres espectador. Usa §e/natura:lobby§r para volver al lobby.");
      if (hunt.music) playMusic(player);
    } else if (s.mode !== "free") sendToLobby(player);
  }, 2);
});

world.afterEvents.entityHurt.subscribe(({ hurtEntity: player, damage, damageSource }) => {
  if (player.typeId !== "minecraft:player") return;
  const s = st(player);
  const attacker = damageSource?.damagingEntity;
  if (attacker?.typeId === "minecraft:player" && attacker.id !== player.id) {
    s.attacker = attacker.id;
    s.attackerTick = system.currentTick;
    s.hurtTick = system.currentTick;
    st(attacker).hurtTick = system.currentTick;
    // no friendly fire among hunters: give the health back
    if (s.mode === "hunt" && st(attacker).mode === "hunt" && s.role === "hunter" && st(attacker).role === "hunter" && !S.hunt.friendlyFire) {
      try {
        const h = player.getComponent("minecraft:health");
        if (h.currentValue > 0) h.setCurrentValue(Math.min(h.effectiveMax, h.currentValue + damage));
      } catch {}
    }
  }
}, { entityTypes: ["minecraft:player"] });

world.afterEvents.playerLeave.subscribe(({ playerId }) => {
  const s = P.get(playerId);
  const a = duel.queue.indexOf(playerId);
  if (a >= 0) duel.queue.splice(a, 1);
  const b = hunt.queue.indexOf(playerId);
  if (b >= 0) hunt.queue.splice(b, 1);
  hunt.spectators.delete(playerId);
  if (s?.mode === "duel" && s.match) {
    const m = s.match;
    endDuel(m, 1 - m.ids.indexOf(playerId), "el rival abandonó");
  }
  if (s?.mode === "hunt") huntEliminate(playerId, undefined, "abandonó la partida");
  P.delete(playerId);
});

// ------------------------------------------------------------ blocks
world.beforeEvents.playerBreakBlock.subscribe((ev) => {
  const s = P.get(ev.player.id);
  if (s?.mode === "free") return;
  if (s?.mode === "hunt") {
    const { x, y, z } = ev.block.location;
    if (inHunt(x, z) && y > HUNT.floor && y < HUNT.clearTop) return;
  }
  ev.cancel = true;
});

function markDirty(block) {
  const { x, z } = block.location;
  if (inHunt(x, z)) hunt.dirty.add(`${x},${z}`);
}

world.afterEvents.playerBreakBlock.subscribe(({ block }) => markDirty(block));
world.afterEvents.playerPlaceBlock.subscribe(({ block, player }) => {
  const s = P.get(player.id);
  if (s?.mode === "free") return;
  markDirty(block);
  const { x, y, z } = block.location;
  if (s?.mode !== "hunt" || !inHunt(x, z) || y > HUNT.buildLimit) {
    try {
      block.setType("minecraft:air");
    } catch {}
    if (y > HUNT.buildLimit) bar(player, `§cNo puedes construir por encima de Y ${HUNT.buildLimit}.`);
  }
});
try {
  world.afterEvents.blockExplode.subscribe(({ block }) => markDirty(block));
} catch {}

// ------------------------------------------------------------ items
world.afterEvents.itemUse.subscribe(({ source: player, itemStack }) => {
  if (player?.typeId !== "minecraft:player") return;
  const kind = itemKind(itemStack);
  if (!kind) return;
  const s = st(player);
  if (system.currentTick - (s.lastUse ?? -99) < 8) return;
  s.lastUse = system.currentTick;
  if (kind === "selector") openSelector(player);
  else if (kind === "admin") openAdmin(player);
  else if (kind === "leave" && s.mode === "campal") campalLeave(player);
});

// ------------------------------------------------------------ lobby: pads, texts, safety
const PADS = Object.entries(LOBBY.pads);

function padUnder(player) {
  const l = player.location;
  if (l.y < LOBBY.y + 0.5 || l.y > LOBBY.y + 2.5) return null;
  for (const [k, pad] of PADS) if (Math.abs(Math.floor(l.x) - pad.x) <= 1 && Math.abs(Math.floor(l.z) - pad.z) <= 1) return k;
  return null;
}

function padAction(player, key) {
  if (key === "duel") duel.queue.includes(player.id) ? player.sendMessage("§b[Emparejamiento]§r Ya estás en la cola. Usa la brújula para salir.") : duelJoin(player);
  else if (key === "hunt") hunt.queue.includes(player.id) ? player.sendMessage("§c[Caza]§r Ya estás en la cola. Usa la brújula para salir.") : huntJoin(player);
  else if (key === "campal") campalEnter(player);
}

const TEXTS = {
  welcome: { x: 0.5, y: LOBBY.y + 5.4, z: 0.5 },
  duel: { x: LOBBY.pads.duel.x + 0.5, y: LOBBY.y + 3.6, z: LOBBY.pads.duel.z + 0.5 },
  hunt: { x: LOBBY.pads.hunt.x + 0.5, y: LOBBY.y + 3.6, z: LOBBY.pads.hunt.z + 0.5 },
  campal: { x: LOBBY.pads.campal.x + 0.5, y: LOBBY.y + 3.6, z: LOBBY.pads.campal.z + 0.5 },
};

function topLines(key) {
  const t = top(key);
  return t.length ? t.map(([n, s], i) => `§6${i + 1}. §f${n} §7(${s[key]})`).join("\n") : "§7sin partidas todavía";
}

function textFor(key) {
  if (key === "welcome") return "§2§lNATURA PvP\n§fpisa una plataforma o usa la §abrújula";
  if (key === "duel") {
    const busy = duel.matches.filter((m) => m).length;
    return `§b§lEMPAREJAMIENTO\n§71 contra 1 · diamante encantado\n§fen cola: §e${duel.queue.length} §7| §fduelos: §e${busy}\n${S.duel.enabled ? "" : "§c(desactivado)\n"}§6Top victorias\n${topLines("dw")}`;
  }
  if (key === "hunt") {
    const state = hunt.phase === "running" ? `§ccaza en curso §7(${hunt.alive.size} vivos)` : hunt.regen ? "§eregenerando el mapa" : `§fen cola: §e${hunt.queue.length}/${S.hunt.maxPlayers}`;
    return `§c§lCAZA\n§7hasta ${S.hunt.maxPlayers} jugadores · 1 cazado\n${state}\n${S.hunt.enabled ? "" : "§c(desactivado)\n"}§6Top victorias\n${topLines("hw")}`;
  }
  return `§a§lCAMPAL\n§7arena siempre activa · entra cuando quieras\n§fdentro: §e${campalPlayers().length}\n${S.campal.enabled ? "" : "§c(cerrado)\n"}§6Top bajas\n${topLines("ck")}`;
}

function updateTexts() {
  const dim = overworld();
  try {
    if (!dim.getBlock({ x: 0, y: LOBBY.y, z: 0 })) return;
  } catch {
    return;
  }
  let all = [];
  try {
    all = dim.getEntities({ type: "natura:text" });
  } catch {
    return;
  }
  for (const [key, loc] of Object.entries(TEXTS)) {
    const tag = `natura_text_${key}`;
    const mine = all.filter((e) => e.hasTag(tag));
    let e = mine.shift();
    for (const extra of mine) extra.remove();
    if (!e) {
      try {
        e = dim.spawnEntity("natura:text", loc);
        e.addTag(tag);
      } catch {
        continue;
      }
    }
    const text = textFor(key);
    if (e.nameTag !== text) e.nameTag = text;
    if (dist2(e.location, loc) > 0.1 || Math.abs(e.location.y - loc.y) > 0.1) e.teleport(loc);
  }
}

// ------------------------------------------------------------ the main loop
let tick = 0;
system.runInterval(() => {
  tick++;
  const slow = tick % 8 === 0;
  for (const player of world.getPlayers()) {
    const s = st(player);
    const l = player.location;
    if (s.mode === "lobby") {
      if (!built("lobby")) {
        if (l.y < LOBBY.y - 4) tp(player, { x: 0.5, y: 106, z: 0.5 });
        effect(player, "slow_falling", 5, 0);
        continue;
      }
      if (l.y < LOBBY.y - 20 || Math.abs(l.x) > 60 || Math.abs(l.z) > 60) tp(player, LOBBY.spawn);
      if (slow) {
        effect(player, "resistance", 12, 255);
        effect(player, "saturation", 12, 255);
        setMode(player, GM.adventure);
        const inv = player.getComponent("minecraft:inventory")?.container;
        if (inv) {
          if (itemKind(inv.getItem(0)) !== "selector") inv.setItem(0, ITEMS.selector());
          const has = itemKind(inv.getItem(8)) === "admin";
          if (isAdmin(player) && !has) inv.setItem(8, ITEMS.admin());
          if (!isAdmin(player) && has) inv.setItem(8, undefined);
        }
      }
      const pad = padUnder(player);
      if (pad && pad !== s.pad) padAction(player, pad);
      s.pad = pad;
    } else if (s.mode === "duel" && s.match) {
      const sp = s.match.spawns[s.match.ids.indexOf(player.id)];
      if (s.match.phase === "countdown" && dist2(l, sp) > 0.5) tp(player, sp);
      else if (l.y < DUEL.y - 3 || !insideArea(`duel${s.match.i}`, l.x, l.z)) tp(player, sp);
    } else if (s.mode === "hunt") {
      if (s.lockAt && hunt.headLeft > 0 && dist2(l, s.lockAt) > 1) tp(player, s.lockAt);
      if (!inHunt(Math.floor(l.x), Math.floor(l.z)) || l.y < HUNT.floor) {
        const x = Math.max(HUNT.x0 + 3, Math.min(HUNT.x1 - 3, Math.floor(l.x)));
        const z = Math.max(HUNT.z0 + 3, Math.min(HUNT.z1 - 3, Math.floor(l.z)));
        tp(player, { x: x + 0.5, y: huntSurface(x, z).y + 1, z: z + 0.5 });
      }
    } else if (s.mode === "hunt_spec") {
      if (!insideArea("hunt", l.x, l.z, 20) || l.y > HUNT.clearTop + 60) tp(player, huntCenter());
    } else if (s.mode === "campal") {
      if (l.y < CAMPAL.y - 4 || !insideArea("campal", l.x, l.z)) spawnInCampal(player, false);
    }
  }
}, 5);

system.runInterval(() => {
  try {
    duelTick();
  } catch (e) {
    console.warn(`[Natura PvP] duelo: ${e}`);
  }
  try {
    huntTick();
  } catch (e) {
    console.warn(`[Natura PvP] caza: ${e}`);
  }
  if (progress.busy) {
    const text = `§7Construyendo el mapa: §f${progress.label} §e${pct()}%`;
    for (const p of world.getPlayers()) if (isAdmin(p) || !built("lobby") || st(p).mode === "lobby") bar(p, text);
  }
}, SEC);

system.runInterval(updateTexts, 2 * SEC);

function pct() {
  return progress.total ? Math.floor((progress.done / progress.total) * 100) : 0;
}

// ------------------------------------------------------------ building the map
async function ensureBuilt() {
  for (const id of ["lobby", "duel0", "duel1", "campal", "hunt"]) {
    if (built(id)) continue;
    const before = world.getDynamicProperty(`natura:built:${id}`);
    const ok = await buildArea(id, before !== undefined);
    if (ok) world.setDynamicProperty(`natura:built:${id}`, CFG.buildVersion);
    if (id === "lobby" && ok) {
      for (const p of world.getPlayers()) {
        if (st(p).mode !== "lobby") continue;
        sendToLobby(p);
        title(p, "§2§lNATURA PvP", "§fel mapa se está terminando de construir", 60);
      }
    }
    if (ok) world.sendMessage(`§2[Natura PvP]§r ${AREA[id].name} lista.`);
  }
  if (world.getDynamicProperty("natura:huntDirty") === true && built("hunt")) regenHunt(true);
}

async function rebuild(id) {
  world.setDynamicProperty(`natura:built:${id}`, "rebuilding");
  if (id === "hunt") hunt.regen = true;
  const ok = await buildArea(id, true);
  if (ok) world.setDynamicProperty(`natura:built:${id}`, CFG.buildVersion);
  if (id === "hunt") {
    hunt.regen = false;
    hunt.dirty.clear();
    world.setDynamicProperty("natura:huntDirty", false);
  }
  world.sendMessage(`§2[Natura PvP]§r ${AREA[id].name} reconstruida${ok ? "" : " (con errores)"}.`);
}

world.afterEvents.worldLoad.subscribe(() => {
  loadSettings();
  loadStats();
  applyGamerules();
  campalSidebar();
  ensureBuilt();
});

// ------------------------------------------------------------ the mode selector
async function openSelector(player) {
  const s = st(player);
  if (s.mode !== "lobby") {
    if (s.mode === "campal") return campalLeave(player);
    return player.sendMessage("§7Solo puedes elegir modo desde el lobby.");
  }
  const inDuel = duel.queue.includes(player.id), inHuntQ = hunt.queue.includes(player.id);
  const form = new ui.ActionFormData().title("§l§2Natura PvP").body("§fElige un modo de juego.\n");
  const actions = [];
  const add = (text, icon, fn) => {
    form.button(text, icon);
    actions.push(fn);
  };
  add(inDuel ? "§cSalir de la cola\n§8Emparejamiento" : `§b§lEmparejamiento\n§8en cola: ${duel.queue.length}`, "textures/items/diamond_sword",
    () => (inDuel ? duelLeave(player) : duelJoin(player)));
  if (hunt.phase === "running") add(`§c§lCaza §r§8(en curso)\n§8mirar como espectador`, "textures/items/bow_standby", () => huntSpectate(player));
  else add(inHuntQ ? "§cSalir de la cola\n§8Caza" : `§c§lCaza\n§8${hunt.queue.length}/${S.hunt.maxPlayers} jugadores`, "textures/items/bow_standby",
    () => (inHuntQ ? huntLeave(player) : huntJoin(player)));
  add(`§a§lCampal\n§8dentro: ${campalPlayers().length}`, "textures/items/iron_sword", () => campalEnter(player));
  add("§e§lMis estadísticas", "textures/items/book_normal", () => openStats(player));
  if (isAdmin(player)) add("§c§lPanel de administración", "textures/items/clock_item", () => openAdmin(player));
  const r = await showForm(player, form);
  if (r && !r.canceled && actions[r.selection]) actions[r.selection]();
}

async function openStats(player, name = player.name) {
  const s = STATS[name] ?? {};
  const lines = Object.entries(STAT_NAMES).map(([k, label]) => `§7${label}: §f${s[k] ?? 0}`);
  const kd = (s.k ?? 0) / Math.max(1, s.d ?? 0);
  const form = new ui.ActionFormData().title(`§l${name}`).body(`${lines.join("\n")}\n§7K/D: §f${kd.toFixed(2)}\n `).button("Cerrar");
  await showForm(player, form);
}

// ------------------------------------------------------------ the admin panel
async function menu(player, titleText, body, buttons) {
  const form = new ui.ActionFormData().title(titleText).body(body);
  for (const [text, , icon] of buttons) form.button(text, icon);
  const r = await showForm(player, form);
  if (!r || r.canceled || !buttons[r.selection]) return;
  await buttons[r.selection][1]();
}

async function confirm(player, titleText, body) {
  const form = new ui.MessageFormData().title(titleText).body(body).button1("§cSí").button2("No");
  const r = await showForm(player, form);
  return r && !r.canceled && r.selection === 0;
}

// fields: [key, type, label, ...]: toggle | slider(min, max, step) | dropdown(options)
async function settingsForm(player, section, titleText, fields) {
  const form = new ui.ModalFormData().title(titleText);
  for (const [key, type, label, a, b, c] of fields) {
    const v = S[section][key];
    if (type === "toggle") form.toggle(label, { defaultValue: !!v });
    else if (type === "slider") form.slider(label, a, b, { valueStep: c, defaultValue: Math.max(a, Math.min(b, v)) });
    else if (type === "dropdown") form.dropdown(label, a, { defaultValueIndex: v });
  }
  form.submitButton("Guardar");
  const r = await showForm(player, form);
  if (!r || r.canceled || !r.formValues) return false;
  fields.forEach(([key], i) => {
    if (r.formValues[i] !== undefined) S[section][key] = r.formValues[i];
  });
  saveSettings();
  player.sendMessage("§a[Admin] Ajustes guardados.");
  return true;
}

function requireAdmin(player) {
  if (isAdmin(player)) return true;
  player.sendMessage(`§c[Natura PvP] Necesitas la etiqueta "${ADMIN_TAG}" (/tag @s add ${ADMIN_TAG}).`);
  return false;
}

async function openAdmin(player) {
  if (!requireAdmin(player)) return;
  const free = st(player).mode === "free";
  await menu(player, "§l§cPanel de administración", status(), [
    ["§b§lEmparejamiento", () => adminDuel(player), "textures/items/diamond_sword"],
    ["§c§lCaza", () => adminHunt(player), "textures/items/bow_standby"],
    ["§a§lCampal", () => adminCampal(player), "textures/items/iron_sword"],
    ["§d§lKits", () => adminKits(player), "textures/items/diamond_chestplate"],
    ["§e§lMundo y tiempo", () => adminWorld(player), "textures/items/clock_item"],
    ["§6§lJugadores", () => adminPlayers(player), "textures/items/name_tag"],
    ["§3§lTeletransporte", () => adminTeleport(player), "textures/items/ender_pearl"],
    [free ? "§2§lSalir del modo libre" : "§2§lModo libre (creativo)", () => toggleFree(player), "textures/items/diamond_pickaxe"],
    ["§4§lReconstruir el mapa", () => adminRebuild(player), "textures/blocks/grass_side_carried"],
    ["§8§lEstadísticas y ajustes", () => adminReset(player), "textures/items/book_writable"],
  ]);
}

function status() {
  const duels = duel.matches.filter((m) => m && m.phase !== "end").map((m) => `§7  arena ${m.i + 1}: §f${m.names[0]} vs ${m.names[1]}`);
  const huntText = hunt.phase === "running" ? `§cen curso §7(cazado: ${hunt.names[hunt.hunted]}, vivos ${hunt.alive.size}, ${fmtTime(hunt.timeLeft)})`
    : hunt.regen ? `§eregenerando ${pct()}%` : `§f${hunt.phase === "countdown" ? `empieza en ${hunt.countdown}s` : "esperando"} §7(cola ${hunt.queue.length}/${S.hunt.maxPlayers})`;
  const builds = ["lobby", "duel0", "duel1", "campal", "hunt"].filter((id) => !built(id)).map((id) => AREA[id].name);
  return [
    `§fJugadores: §e${world.getPlayers().length}`,
    `§bEmparejamiento: §f${S.duel.enabled ? "activo" : "§cdesactivado"} §7(cola ${duel.queue.length})`,
    ...duels,
    `§cCaza: ${S.hunt.enabled ? huntText : "§cdesactivada"}`,
    `§aCampal: §f${S.campal.enabled ? "abierto" : "§ccerrado"} §7(${campalPlayers().length} dentro)`,
    builds.length ? `§eSin construir: ${builds.join(", ")}${progress.busy ? ` (${progress.label} ${pct()}%)` : ""}` : "§7Mapa construido.",
    " ",
  ].join("\n");
}

async function adminDuel(player) {
  await menu(player, "§l§bEmparejamiento", `§7Cuenta atrás: §f${S.duel.countdown} s§7, duración máxima: §f${S.duel.maxTime ? fmtTime(S.duel.maxTime) : "sin límite"}`, [
    ["Ajustes", () => settingsForm(player, "duel", "Emparejamiento", [
      ["enabled", "toggle", "Modo activado"],
      ["countdown", "slider", "Segundos antes de empezar", 3, 30, 1],
      ["maxTime", "slider", "Duración máxima (s, 0 = sin límite)", 0, 900, 30],
      ["arenas", "slider", "Arenas en uso", 1, DUEL.centers.length, 1],
    ])],
    ["Terminar todos los duelos (empate)", () => {
      for (const m of duel.matches) if (m && m.phase !== "end") endDuel(m, undefined, "un administrador terminó el duelo");
    }],
    ["Vaciar la cola", () => {
      for (const id of duel.queue) byId(id)?.sendMessage("§b[Emparejamiento]§r Un administrador vació la cola.");
      duel.queue = [];
    }],
  ]);
}

async function adminHunt(player) {
  await menu(player, "§l§cCaza", status(), [
    ["Ajustes", () => settingsForm(player, "hunt", "Caza", [
      ["enabled", "toggle", "Modo activado"],
      ["maxPlayers", "slider", "Jugadores máximos", 2, 5, 1],
      ["minPlayers", "slider", "Jugadores mínimos para empezar", 2, 5, 1],
      ["lobbyCountdown", "slider", "Espera en la cola antes de empezar (s)", 5, 120, 5],
      ["headStart", "slider", "Ventaja del cazado (s)", 0, 60, 5],
      ["timeLimit", "slider", "Duración de la caza (s)", 60, 1800, 60],
      ["reveal", "slider", "Revelar la posición del cazado cada (s, 0 = nunca)", 0, 180, 15],
      ["music", "toggle", "Canción épica en el duelo final (1 contra 1)"],
      ["friendlyFire", "toggle", "Fuego amigo entre cazadores"],
      ["fullRegenEvery", "slider", "Regeneración completa cada N cazas (0 = solo lo modificado)", 0, 20, 1],
    ])],
    ["Forzar inicio", () => {
      if (hunt.phase === "running" || hunt.phase === "ending") return player.sendMessage("§c[Admin] Ya hay una caza en curso.");
      if (hunt.regen) return player.sendMessage("§c[Admin] El mapa se está regenerando.");
      if (hunt.queue.length < 2) return player.sendMessage("§c[Admin] Hacen falta al menos 2 jugadores en la cola.");
      startHunt();
    }],
    ["Detener la caza", () => {
      if (hunt.phase !== "running") return player.sendMessage("§c[Admin] No hay ninguna caza en curso.");
      endHunt("hunted", "un administrador detuvo la caza");
    }],
    ["Elegir el próximo cazado", () => chooseHunted(player)],
    ["Regenerar lo modificado", () => {
      if (hunt.phase === "running") return player.sendMessage("§c[Admin] Espera a que acabe la caza.");
      regenHunt(false);
    }],
    ["Regeneración completa", async () => {
      if (hunt.phase === "running") return player.sendMessage("§c[Admin] Espera a que acabe la caza.");
      if (await confirm(player, "Regeneración completa", "Se reconstruye todo el mapa de caza (365x365). Tarda un rato.")) regenHunt(true);
    }],
    ["Probar la canción", () => playMusic(player)],
    ["Parar la canción", () => stopMusic(player)],
  ]);
}

async function chooseHunted(player) {
  const list = world.getPlayers();
  const form = new ui.ModalFormData().title("Próximo cazado")
    .dropdown("Jugador", ["Aleatorio", ...list.map((p) => p.name)], { defaultValueIndex: 0 });
  const r = await showForm(player, form);
  if (!r || r.canceled) return;
  const i = r.formValues[0];
  hunt.nextHunted = i > 0 ? list[i - 1].id : undefined;
  player.sendMessage(`§a[Admin] Próximo cazado: ${i > 0 ? list[i - 1].name : "aleatorio"} (si está en la cola).`);
}

async function adminCampal(player) {
  await menu(player, "§l§aCampal", `§7Dentro: §f${campalPlayers().map((p) => p.name).join(", ") || "nadie"}`, [
    ["Ajustes", async () => {
      if (await settingsForm(player, "campal", "Campal", [
        ["enabled", "toggle", "Arena abierta"],
        ["reward", "toggle", "Premio por baja (regeneración + manzana dorada)"],
        ["spawnProtection", "slider", "Protección al aparecer (s)", 0, 10, 1],
        ["combatTag", "slider", "Segundos sin daño para poder salir", 0, 30, 1],
        ["sidebar", "toggle", "Mostrar la tabla de bajas a la derecha"],
      ])) {
        campalSidebar();
        if (!S.campal.enabled) for (const p of campalPlayers()) sendToLobby(p, "§a[Campal]§r La arena se ha cerrado.");
      }
    }],
    ["Reiniciar la tabla de bajas", () => {
      try {
        world.scoreboard.removeObjective(OBJ);
      } catch {}
      campalSidebar();
      for (const p of campalPlayers()) campalObjective().setScore(p, 0);
      player.sendMessage("§a[Admin] Tabla de bajas reiniciada.");
    }],
    ["Enviar a todos al lobby", () => {
      for (const p of campalPlayers()) sendToLobby(p, "§a[Campal]§r Un administrador te envió al lobby.");
    }],
  ]);
}

async function adminKits(player) {
  await menu(player, "§l§dKits", "§7Elige un kit para verlo, probarlo o cambiarlo por tu inventario.", KIT_IDS.map((id) => [
    `${DEFAULT_KITS[id].name}${getKit(id).custom ? " §8(personalizado)" : ""}`, () => adminKit(player, id),
  ]));
}

async function adminKit(player, id) {
  const kit = getKit(id);
  const extra = id === "hunted" ? "\n§eEste es el kit base: con 2, 3 y 4 cazadores sube de nivel (protección, filo, poder, más manzanas, velocidad y vida extra).\n" : "";
  await menu(player, `§l${kit.name}`, `§7${kit.desc}\n${extra}\n${describeKit(kit)}\n `, [
    ["Recibir el kit (probar)", () => {
      if (st(player).mode !== "free") return player.sendMessage("§c[Admin] Entra en el modo libre para probar kits sin perder los objetos del lobby.");
      giveKit(player, id === "hunted" ? scaledHuntedKit(1) : kit);
    }],
    ["Guardar mi inventario como este kit", async () => {
      if (!(await confirm(player, "Guardar kit", `Tu inventario y armadura actuales serán el kit "${kit.name}".`))) return;
      try {
        const n = saveKitFrom(player, id);
        player.sendMessage(n ? `§a[Admin] Kit "${kit.name}" guardado (${n} objetos).` : "§c[Admin] Tu inventario está vacío.");
      } catch (e) {
        player.sendMessage(`§c[Admin] ${e.message ?? e}`);
      }
    }],
    ["Restaurar el kit por defecto", () => {
      resetKit(id);
      player.sendMessage(`§a[Admin] Kit "${kit.name}" restaurado.`);
    }],
  ]);
}

async function adminWorld(player) {
  const form = new ui.ModalFormData().title("Mundo y tiempo")
    .dropdown("Hora", TIMES.map((t) => t[0]), { defaultValueIndex: S.world.time })
    .toggle("Congelar la hora", { defaultValue: S.world.lockTime })
    .dropdown("Clima", WEATHERS.map((w) => w[0]), { defaultValueIndex: S.world.weather })
    .toggle("Congelar el clima", { defaultValue: S.world.lockWeather })
    .toggle("Regeneración natural de vida", { defaultValue: S.world.naturalRegen })
    .textField("Mensaje para todos (opcional)", "escribe un anuncio", { defaultValue: "" })
    .submitButton("Aplicar");
  const r = await showForm(player, form);
  if (!r || r.canceled || !r.formValues) return;
  const [time, lockTime, weather, lockWeather, naturalRegen, msg] = r.formValues;
  Object.assign(S.world, { time, lockTime, weather, lockWeather, naturalRegen });
  saveSettings();
  applyWorld();
  if (typeof msg === "string" && msg.trim()) {
    world.sendMessage(`§6[Anuncio]§r ${msg.trim()}`);
    for (const p of world.getPlayers()) title(p, "§6§lANUNCIO", `§f${msg.trim()}`, 60);
  }
  player.sendMessage("§a[Admin] Mundo actualizado.");
}

async function adminPlayers(player) {
  const list = world.getPlayers();
  const modeName = { lobby: "lobby", duel: "duelo", hunt: "caza", hunt_spec: "espectador", campal: "campal", free: "modo libre" };
  await menu(player, "§l§6Jugadores", "§7Elige un jugador.", list.map((p) => [
    `${isAdmin(p) ? "§c" : "§f"}${p.name}\n§8${modeName[st(p).mode] ?? st(p).mode}`, () => adminPlayer(player, p),
  ]));
}

async function adminPlayer(player, target) {
  if (!valid(target)) return;
  const admin = isAdmin(target);
  await menu(player, `§l${target.name}`, `§7Modo: §f${st(target).mode}\n§7Admin: §f${admin ? "sí" : "no"}`, [
    ["Enviar al lobby / sacar de la partida", () => removeFromGame(target, `§e[Admin]§r ${player.name} te envió al lobby.`)],
    [admin ? "Quitar admin" : "Dar admin", () => {
      if (admin) target.removeTag(ADMIN_TAG);
      else target.addTag(ADMIN_TAG);
      player.sendMessage(`§a[Admin] ${target.name} ${admin ? "ya no es" : "ahora es"} administrador.`);
      target.sendMessage(admin ? "§7Ya no eres administrador." : "§aAhora eres administrador: usa el reloj o /natura:admin.");
    }],
    ["Curar", () => heal(target)],
    ["Ver estadísticas", () => openStats(player, target.name)],
    ["Ir hacia él", () => {
      if (st(player).mode !== "free") toggleFree(player);
      tp(player, target.location);
    }],
    ["Que sea el próximo cazado", () => {
      hunt.nextHunted = target.id;
      player.sendMessage(`§a[Admin] ${target.name} será el próximo cazado si está en la cola.`);
    }],
    ["Reiniciar sus estadísticas", () => {
      delete STATS[target.name];
      statsDirty = true;
    }],
  ]);
}

function removeFromGame(target, message) {
  const s = st(target);
  leaveQueues(target);
  if (s.mode === "duel" && s.match) {
    const m = s.match;
    endDuel(m, 1 - m.ids.indexOf(target.id), "un administrador sacó a un jugador");
  } else if (s.mode === "hunt") huntEliminate(target.id, undefined, "fue retirado por un administrador");
  hunt.spectators.delete(target.id);
  sendToLobby(target, message);
}

function toggleFree(player) {
  const s = st(player);
  if (s.mode === "free") return sendToLobby(player, "§7Saliste del modo libre.");
  removeFromGame(player);
  s.mode = "free";
  clearPlayer(player);
  clearEffects(player);
  setMode(player, GM.creative);
  player.sendMessage("§2[Admin]§r Modo libre: creativo, sin límites del mapa. Puedes romper y poner bloques (fuera de la caza no se regeneran). Vuelve con el panel o /natura:lobby.");
}

async function adminTeleport(player) {
  const go = (loc) => {
    if (st(player).mode !== "free") toggleFree(player);
    tp(player, loc);
  };
  const d = DUEL.centers;
  await menu(player, "§l§3Teletransporte", "§7Te pone en modo libre (creativo) para moverte por el mapa.", [
    ["Lobby", () => sendToLobby(player)],
    ["Arena de emparejamiento 1", () => go({ x: d[0].x + 0.5, y: DUEL.y + 6, z: d[0].z + 0.5 })],
    ["Arena de emparejamiento 2", () => go({ x: d[1].x + 0.5, y: DUEL.y + 6, z: d[1].z + 0.5 })],
    ["Campal", () => go({ x: CAMPAL.cx + 0.5, y: CAMPAL.y + 8, z: CAMPAL.cz + 0.5 })],
    ["Caza (centro)", () => go(huntCenter())],
  ]);
}

async function adminRebuild(player) {
  const ids = ["lobby", "duel0", "duel1", "campal", "hunt"];
  await menu(player, "§l§4Reconstruir", "§7Vuelve a colocar todos los bloques de una zona tal como estaba al principio (los cambios hechos a mano se pierden).", ids.map((id) => [
    AREA[id].name, async () => {
      if (id === "hunt" && hunt.phase === "running") return player.sendMessage("§c[Admin] Espera a que acabe la caza.");
      if (id.startsWith("duel") && duel.matches[Number(id[4])]) return player.sendMessage("§c[Admin] Hay un duelo en esa arena.");
      if (await confirm(player, `Reconstruir: ${AREA[id].name}`, "¿Seguro?")) rebuild(id);
    },
  ]));
}

async function adminReset(player) {
  await menu(player, "§l§8Estadísticas y ajustes", "", [
    ["Ver el ranking", () => {
      const lines = ["k", "dw", "hw", "ck"].map((k) => `§6${STAT_NAMES[k]}\n${topLines(k)}`);
      return menu(player, "Ranking", lines.join("\n\n") + "\n ", [["Cerrar", () => {}]]);
    }],
    ["Reiniciar todas las estadísticas", async () => {
      if (!(await confirm(player, "Reiniciar estadísticas", "Se borran las estadísticas de todos los jugadores."))) return;
      STATS = {};
      statsDirty = true;
      player.sendMessage("§a[Admin] Estadísticas reiniciadas.");
    }],
    ["Restaurar los ajustes por defecto", async () => {
      if (!(await confirm(player, "Ajustes por defecto", "Los modos, tiempos y el mundo vuelven a los valores iniciales (los kits no)."))) return;
      S = structuredCloneSafe(DEFAULTS);
      saveSettings();
      applyWorld();
      campalSidebar();
      player.sendMessage("§a[Admin] Ajustes restaurados.");
    }],
  ]);
}

// ------------------------------------------------------------ commands
function originPlayer(origin) {
  const e = origin?.sourceEntity ?? origin?.initiator;
  return e?.typeId === "minecraft:player" ? e : undefined;
}

system.beforeEvents.startup.subscribe((ev) => {
  const reg = ev.customCommandRegistry;
  if (!reg) return;
  const ok = (message) => ({ status: mc.CustomCommandStatus.Success, message });
  const fail = (message) => ({ status: mc.CustomCommandStatus.Failure, message });
  const any = { permissionLevel: mc.CommandPermissionLevel.Any, cheatsRequired: false };
  const register = (def, fn) => {
    try {
      reg.registerCommand(def, fn);
    } catch (e) {
      console.warn(`[Natura PvP] comando ${def.name}: ${e}`);
    }
  };
  register({ ...any, name: "natura:menu", description: "Abre el selector de modos de Natura PvP" }, (origin) => {
    const p = originPlayer(origin);
    if (!p) return fail("Solo jugadores.");
    system.run(() => openSelector(p));
    return ok();
  });
  register({ ...any, name: "natura:lobby", description: "Vuelve al lobby (o sal de la cola)" }, (origin) => {
    const p = originPlayer(origin);
    if (!p) return fail("Solo jugadores.");
    system.run(() => {
      const s = st(p);
      if (s.mode === "campal") campalLeave(p);
      else if (s.mode === "hunt_spec" || s.mode === "free") {
        hunt.spectators.delete(p.id);
        sendToLobby(p);
      } else if (s.mode === "lobby") {
        leaveQueues(p);
        sendToLobby(p, "§7Estás en el lobby (y fuera de las colas).");
      } else p.sendMessage("§cNo puedes salir en mitad de una partida.");
    });
    return ok();
  });
  register({ ...any, name: "natura:admin", description: "Abre el panel de administración (etiqueta admin)" }, (origin) => {
    const p = originPlayer(origin);
    if (!p) return fail("Solo jugadores.");
    system.run(() => openAdmin(p));
    return ok();
  });
  register({
    permissionLevel: mc.CommandPermissionLevel.GameDirectors, cheatsRequired: false, name: "natura:hacer_admin",
    description: "Da la etiqueta admin de Natura PvP", mandatoryParameters: [{ type: mc.CustomCommandParamType.PlayerSelector, name: "jugadores" }],
  }, (origin, players) => {
    system.run(() => {
      for (const p of players ?? []) {
        p.addTag(ADMIN_TAG);
        p.sendMessage("§aAhora eres administrador de Natura PvP: usa el reloj o /natura:admin.");
      }
    });
    return ok(`Admin dado a ${players?.length ?? 0} jugador(es).`);
  });
  register({
    permissionLevel: mc.CommandPermissionLevel.GameDirectors, cheatsRequired: false, name: "natura:quitar_admin",
    description: "Quita la etiqueta admin de Natura PvP", mandatoryParameters: [{ type: mc.CustomCommandParamType.PlayerSelector, name: "jugadores" }],
  }, (origin, players) => {
    system.run(() => {
      for (const p of players ?? []) p.removeTag(ADMIN_TAG);
    });
    return ok(`Admin quitado a ${players?.length ?? 0} jugador(es).`);
  });
});
